        {"구절":"렘 7:12-14", "연결점":"실로를 보라 - 하나님이 거하시던 곳도 버리셨음", "구분":"구약"},
        {"구절":"겔 10:18", "연결점":"여호와의 영광이 성전 문지방에서 떠남", "구분":"구약"},
        {"구절":"사 1:13", "연결점":"너희의 무익한 제물을 다시 가져오지 말라 - 제물의 거부", "구분":"구약"},
        {"구절":"히 13:10", "연결점":"우리에게 제단이 있는데 장막에서 섬기는 자들이 이 제단에서 먹을 권이 없나니 - 참 제단", "구분":"신약"},
        {"구절":"골 2:9", "연결점":"신성의 모든 충만이 육체로 거하시고 - 참 성소이신 그리스도", "구분":"신약"},
        {"구절":"마 27:39-44", "연결점":"조롱과 모욕을 받으신 그리스도 - 찬양이 조롱으로 바뀐 자리", "구분":"신약"},
        {"구절":"계 21:22", "연결점":"성에서 성전을 내가 보지 못하였으니 - 하나님 자신이 성전이심", "구분":"신약"}
