        {"원어":"מִי יִרְפָּא־לָךְ (미 이르파 라크)", "의미_문법":"누가 너를 고쳐주랴 - 의문사 + 동사 칼형. 치유자를 찾는 물음", "설교포인트":"인간 치유의 한계와 참 치유자를 가리키는 물음"}
