        {"상황":"타인을 위로하려 하나 말을 잃은 상담자/목회자", "성경원리":"예레미야도 말을 찾지 못했다. 때로는 함께 눈물 흘림이 가장 깊은 위로다", "실제적용":"말보다 존재로, 설명보다 동행으로 위로하라. 그리스도께 기도하며 인도받으라"}
