        {"상황":"공개적 수치를 경험하여 회복이 어려운 분", "성경원리":"그리스도께서 친히 공개적 수치를 당하셨다. 그분 안에서 수치는 영광으로 바뀐다(히 12:2)", "실제적용":"수치를 숨기기만 하지 말고 그리스도께 가져가라. 그분이 수치를 영광의 자리로 바꾸신다"},
        {"상황":"과거의 영광과 현재의 초라함 사이에서 괴로운 분", "성경원리":"모든 인간적 영광은 일시적이다. 하나님이 주신 영광만이 영원하다", "실제적용":"과거에 매이지 말고 그리스도 안에서 새 정체성을 붙들라. 인간의 박수보다 하나님의 인정을 구하라"},
        {"상황":"타인의 조롱과 비웃음에 상처받는 분", "성경원리":"그리스도도 조롱을 받으셨다. 그분의 고난에 참여하는 것이 때로는 영광이다", "실제적용":"조롱 앞에서 그리스도를 닮아가라. 그분처럼 침묵으로 반응하고 아버지께 맡기라(벧전 2:23)"}
