        {"항목":"계획하신 일의 성취", "내용":"예레미야는 40년간 이 심판을 선포했으며, 이제 그 모든 예언이 성취됨. 하나님은 갑작스럽게 심판하지 않으시고 오랫동안 경고하신 후 집행하심", "목회적활용":"하나님의 오래 참으심은 심판의 부재가 아니라 유예일 뿐이다"},
        {"항목":"원수의 뿔의 높아짐", "내용":"바벨론이 이스라엘을 정복함으로써 일시적 전성기를 맞음. 그러나 이는 하나님이 들어 쓰신 일시적 현상", "목회적활용":"악한 자의 일시적 번성을 보고 흔들리지 말라"}
