        {"상황":"회개의 기회를 미루고 있는 분", "성경원리":"긍휼의 하나님도 긍휼을 거두실 때가 있다. 오래 참으심이 끝이 없지는 않다", "실제적용":"지금 회개하라. '내일'이라는 말은 구원의 단어가 아니다. '오늘'이 구원의 날이다(고후 6:2)"}
