        {"원어":"חוֹמַת בַּת־צִיּוֹן (호마트 바트 치욘)", "의미_문법":"딸 시온의 성벽 - 명사 연계형. 의인화된 성벽", "설교포인트":"무너진 성벽에게 주는 애도의 명령"},
        {"원어":"הוֹרִידִי כַנַּחַל דִּמְעָה (호리디 칸나할 디므아)", "의미_문법":"눈물을 시내처럼 흘리라 - 동사 히필형 + 명사. 명령형", "설교포인트":"애도도 명령이 될 수 있음 - 회개의 진정성"},
        {"원어":"אַל־תִּדֹּם (알 티돔)", "의미_문법":"쉬지 말라 - 부정 + 동사 칼형. 잠잠하지 말라", "설교포인트":"지속적인 기도와 애통의 부르심"}
