        {"항목":"뼈가 꺾임의 표현", "내용":"히브리어에서 '뼈가 꺾인다'는 것은 극단의 고통과 절망을 나타냄. 육체적, 정신적, 영적 붕괴의 총체적 표현", "목회적활용":"전인격적 고통을 이해하라"},
        {"항목":"포로의 육체적 고통", "내용":"바벨론 포로 과정에서 죽음의 행진이 있었다. 많은 사람들이 탈진과 굶주림으로 쓰러졌다", "목회적활용":"역사 속 고난의 실재를 잊지 말라"}
