        {"교리":"육체의 쇠함과 영혼의 갱신", "설명":"외인은 낡아지나 속사람은 새로워지는 것이 그리스도인의 역설이다. 육체의 쇠함이 영혼의 성숙을 막지 못한다", "관련구절":"고후 4:16, 롬 8:10-11, 빌 3:21"},
        {"교리":"고난의 육체성", "설명":"고난은 추상적이지 않다. 살과 뼈를 통해 경험된다. 그리스도도 육체로 고난당하셨다", "관련구절":"히 2:14, 히 5:7-8, 벧전 4:1"}
