    "표5_매튜헨리": [
        {"영어원문":"My flesh and my skin hath he made old. His body was worn out with fatigue, his skin wrinkled with grief.", "한국어번역":"내 살과 내 가죽을 그가 낡게 하셨다. 그의 몸은 피로로 쇠하였고, 그의 가죽은 슬픔으로 주름졌다.", "핵심통찰":"슬픔은 육체에 그 흔적을 남긴다"},
        {"영어원문":"He hath broken my bones. Inward troubles were added to outward; the very bones were broken.", "한국어번역":"그가 내 뼈를 꺾으셨다. 외적 고난에 내적 고난이 더해졌고, 바로 뼈까지 꺾였다.", "핵심통찰":"가장 깊은 곳의 고통은 뼈의 고통이다"},
        {"영어원문":"When God is against us, all things are against us. No part of the body can rest when the soul is troubled.", "한국어번역":"하나님이 우리를 대적하시면 모든 것이 우리를 대적한다. 영혼이 괴로울 때 몸의 어떤 부분도 쉴 수 없다.", "핵심통찰":"영혼과 육체는 분리되지 않는다"}
    ],
    "표6_설교자료": [
        {"대지":"제목", "내용":"살과 뼈가 말할 때 - 전인격적 고난", "예화_적용":"육체와 영혼 모두에 미치는 고난의 깊이에 관한 설교"},
        {"대지":"서론", "내용":"예레미야의 고백은 점점 깊어진다. 어둠의 길에서 반복되는 매질을 거쳐, 이제 그의 살과 가죽이 쇠하고 뼈가 꺾였다고 말한다. 고난이 표면에서 깊은 곳으로 침투한다. 그러나 이 깊은 고난 속에서 예레미야는 하나님을 잃지 않는다", "예화_적용":"한센병 환자를 돌본 다미안 신부는 자신도 그 병에 걸려 죽었다. 그의 살이 썩고 뼈가 드러났지만 그는 마지막까지 사랑을 실천했다"},
        {"대지":"1대지: 살과 가죽의 쇠함 (육체의 한계)", "내용":"고난은 육체에 흔적을 남긴다. 시편 32편에서 다윗도 '종일 신음함으로 내 뼈가 쇠하였도다'라고 고백했다. 영혼의 고통은 육체의 고통이 된다", "예화_적용":"전쟁 포로로 고생한 사람들의 얼굴에는 평생 그 흔적이 남는다. 그러나 그 흔적이 곧 증거가 된다"},
        {"대지":"2대지: 뼈가 꺾인 경험 (존재의 붕괴)", "내용":"뼈가 꺾인다는 것은 존재의 기초가 무너지는 경험이다. 더 이상 서 있을 수 없는 상태. 그러나 바로 그때 하나님께 완전히 의지할 수 있다", "예화_적용":"야곱은 얍복 강가에서 허벅지 관절이 탈골되고서야 하나님을 만났다. 꺾임이 은혜의 시작이다"},
        {"대지":"3대지: 그리스도의 몸 (우리를 위한 꺾임)", "내용":"그리스도는 우리의 뼈가 꺾이지 않도록 자신의 몸을 내어주셨다. '이것은 너희를 위하는 내 몸이니.' 그의 찢기심이 우리의 치유다", "예화_적용":"성찬은 매주 우리에게 상기시킨다. 그리스도의 몸이 찢기심으로 우리의 영혼이 완전해졌다"},
        {"대지":"결론", "내용":"육체가 쇠하는가? 뼈가 꺾이는 고통 속에 있는가? 예레미야처럼 솔직히 고백하라. 그리고 그 고백 속에서 그리스도를 바라보라. 그의 찢기신 몸과 흘리신 피가 당신의 치유다", "예화_적용":"고후 4:16 - '우리의 겉사람은 낡아지나 우리의 속사람은 날로 새로와지도다.' 쇠함 속에 갱신이 있다"}
    ],
