        {"항목":"예레미야의 기도 경험", "내용":"예레미야는 기도의 사람이었다. 그러나 그의 중보기도는 종종 거절당했다 (렘 7:16, 11:14, 14:11)", "목회적활용":"기도가 응답되지 않는 것이 곧 신앙의 실패는 아니다"}
