        {"교리":"응답의 다양성", "설명":"하나님의 응답은 '예', '아니오', '기다려라' 세 가지다. '아니오'도 응답이고 '기다려라'도 응답이다", "관련구절":"고후 12:8-9, 사 55:8-9, 롬 8:28"}
