        {"상황":"인생의 경로가 완전히 틀어진 분", "성경원리":"길에서 벗어남이 길의 끝은 아니다. 하나님은 새로운 길을 준비하신다", "실제적용":"과거의 길에 집착하지 말고 지금 하나님이 여시는 새 길을 보라. 그 길이 더 좋을 수 있다"},
        {"상황":"내면이 찢긴 것 같은 깊은 상처를 입은 분", "성경원리":"찢김 속에도 치유의 가능성이 있다. 호세아 6:1 - '그가 우리를 찢으셨으나 도로 낫게 하시리라'", "실제적용":"상처를 숨기지 말고 주님께 드러내라. 그가 고치실 것이다. 때로는 시간이 걸리지만 반드시 고치신다"}
