        {"상황":"자신이 저주받은 것 같다고 느끼는 분", "성경원리":"고난이 곧 저주는 아니다. 의인 욥과 예레미야도 과녁이 되었다. 고난은 오히려 하나님이 귀히 여기시는 증거일 수 있다", "실제적용":"저주와 연단을 구별하라. 그리스도 안에 있는 당신은 저주 아래 있지 않다. 당신의 고난은 아버지의 사랑의 표현이다"},
        {"상황":"정확한 하나님의 섭리를 의심하는 분", "성경원리":"하나님의 화살은 빗나가지 않는다. 모든 고난은 정확히 계산된 것이다. 우연은 없다", "실제적용":"우연이 아니라고 믿는 것이 신앙이다. 우연이 아니라면 의미가 있다. 그 의미를 찾으라"}
