        {"상황":"고통의 기억이 떠나지 않는 분", "성경원리":"기억은 의지로 지울 수 없다. 그러나 시간과 은혜가 그것을 다룰 수 있다. 하나님은 기억의 치유자이시다", "실제적용":"기억을 억지로 지우려 하지 말라. 그 대신 그 기억을 하나님께 드리라. 그분이 그것을 변화시키실 것이다"},
        {"상황":"신앙생활이 오르락내리락하는 분", "성경원리":"신앙은 일직선이 아니다. 산도 있고 골짜기도 있다. 그러나 전체적인 방향은 위로 향한다", "실제적용":"오늘의 낙심이 영원하지 않다는 것을 기억하라. 내일 다시 일어나라. 신앙은 매일의 새로운 시작이다"}
