        {"상황":"부정적인 생각의 늪에 빠진 분", "성경원리":"마음의 방향을 의도적으로 바꿀 수 있다. 빌립보서 4:8 - '오직 무엇에든지 참되며 무엇에든지 경건하며 무엇에든지 옳으며'", "실제적용":"부정적인 생각이 올라올 때 의도적으로 진리에 마음을 돌이키라. 묵상이 마음의 방향을 바꾼다"},
        {"상황":"소망이 사라진 것 같은 분", "성경원리":"소망은 환경이 아니라 진리에서 온다. 진리를 의도적으로 묵상할 때 소망이 회복된다", "실제적용":"매일 약속의 말씀을 묵상하라. 로마서 8:28, 예레미야 29:11, 시편 23편. 진리가 소망을 회복시킨다"}
