        {"대지":"서론", "내용":"세상은 갚는 것이 정의라 합니다. 그러나 신앙은 견디는 것이 의라 합니다. 예레미야는 뺨을 돌려대라 가르칩니다. 이것이 가장 어려운 신앙입니다", "예화_적용":"마틴 루터 킹의 비폭력 저항 - 예수의 가르침에서 나옴"},
        {"대지":"1대지: 뺨을 돌려대라 (레히)", "내용":"뺨을 치는 것은 가장 큰 모욕입니다. 그것을 돌려댄다는 것은 자존심을 완전히 내려놓는 것입니다. 보복하지 않는 것입니다", "예화_적용":"마 5:39 - 예수의 산상수훈"},
        {"대지":"2대지: 수욕을 견디라 (헤르파)", "내용":"명예가 무너지는 것을 견딥니다. 사람들의 비웃음을 받습니다. 그러나 하나님 앞에서의 명예는 지킵니다", "예화_적용":"히 11:26 - 모세는 그리스도를 위하여 받는 능욕을 애굽의 모든 보화보다 더 큰 재물로 여김"},
        {"대지":"3대지: 배부르도록 (사바)", "내용":"단지 한두 번이 아닌 가득 배부르도록 받습니다. 끝까지 견딥니다. 이것이 십자가의 신앙입니다. 그리스도가 친히 보이신 길입니다", "예화_적용":"본회퍼: '그리스도가 사람을 부르실 때 와서 죽으라 하신다'"},
        {"대지":"결론", "내용":"오늘 누군가 당신의 뺨을 친다면, 어떻게 하시겠습니까? 이 한 절이 신앙의 진위를 시험합니다. 그리스도의 본을 따르십시오", "예화_적용":"수욕을 견딘 자에게 영광이 있습니다"}
