        {"대지":"서론", "내용":"진정한 회개는 자기 죄를 인정하는 것입니다. 우리의 고난이 우리의 죄에서 왔음을 시인하는 것입니다. 예레미야는 이 고백을 이끕니다", "예화_적용":"부흥의 시작은 항상 죄의 자각입니다"},
        {"대지":"1대지: 우리의 범죄 (파샤)", "내용":"파샤는 의도적 반역입니다. 단순한 실수가 아닌 의식적 거역입니다. 우리는 알면서도 죄를 짓습니다", "예화_적용":"롬 7:19 '내가 원하는 바 선은 하지 아니하고 도리어 원치 아니하는 바 악을 행하는도다'"},
        {"대지":"2대지: 우리의 패역 (마라)", "내용":"마라는 완고함입니다. 마음이 굳어 회개하지 않는 상태입니다. 이 또한 우리의 죄입니다", "예화_적용":"히 3:8 '너희 마음을 강퍅케 하지 말라'"},
        {"대지":"3대지: 사하지 아니하심 (살라흐의 부정)", "내용":"용서가 아직 임하지 않음을 인정합니다. 그러나 이것이 절망의 끝이 아닙니다. 용서를 구하는 시작입니다. 죄를 인정하는 자에게 용서가 옵니다", "예화_적용":"요일 1:9 '만일 우리가 우리 죄를 자백하면 저는 미쁘시고 의로우사 우리 죄를 사하시며'"},
        {"대지":"결론", "내용":"오늘 우리의 죄를 인정하십시오. 우리의 패역을 시인하십시오. 그곳에서 용서가 시작됩니다", "예화_적용":"인정하는 자가 용서받습니다"}
